with open(PATH, 'r', encoding='utf-8') as f:
    content = f.read()

# Find each POI's descriptionAdvanced block boundaries: from 'descriptionAdvanced: {' to matching '\n    }'
# We need to also capture the id of the POI right before it.

# Strategy: split by POI entries using id. Iterate backwards; for each match, replace the descriptionAdvanced block.
# Use a custom regex to find descriptionAdvanced opener; parse balanced braces.

def find_descriptionAdvanced_blocks(text):
    """Yield (id, start_idx_of_open_brace, end_idx_after_close_brace, current_block_inner) for each POI."""
    results = []
    # Find each "id: \"...\""
    for m in re.finditer(r'id:\s*"([^"]+)"', text):
        pid = m.group(1)
        # find the next 'descriptionAdvanced: {'
        idx = text.find('descriptionAdvanced:', m.end())
        if idx == -1:
            continue
        # find next '{'
        brace_start = text.find('{', idx)
        # Walk balanced
        depth = 0
        i = brace_start
        while i < len(text):
            c = text[i]
            if c == '{':
                depth += 1
            elif c == '}':
                depth -= 1
                if depth == 0:
                    end = i + 1
                    break
            i += 1
        else:
            continue
        results.append((pid, brace_start, end))
    return results

def build_new_block(existing_inner, new_texts):
    """existing_inner: text inside outer {...}. new_texts: dict lang->text. Add only if existing lang missing or <50 chars."""
    # Parse existing langs
    existing = {}
    for lang in ['de','hu','ro','en']:
        lm = re.search(r'%s:\s*"((?:[^"\\]|\\.)*)"' % lang, existing_inner)
        if lm:
            existing[lang] = lm.group(1)
    # Build merged
    merged = {}
    for lang in ['de','hu','ro','en']:
        cur = existing.get(lang, '')
        if len(cur) >= 50:
            merged[lang] = cur
        else:
            if lang in new_texts:
                merged[lang] = new_texts[lang]
            elif cur:
                merged[lang] = cur
    # Format
    lines = []
    keys = [k for k in ['de','hu','ro','en'] if k in merged]
    for i, lang in enumerate(keys):
        text = merged[lang].replace('\\', '\\\\').replace('"', '\\"')
        sep = ',' if i < len(keys)-1 else ''
        lines.append(f'      {lang}: "{text}"{sep}')
    return '{\n' + '\n'.join(lines) + '\n    }'

blocks = find_descriptionAdvanced_blocks(content)
# Process in reverse so indices don't shift
filled = 0
total_langs_filled = 0
for pid, b_start, b_end in reversed(blocks):
    if pid not in TEXTS:
        continue
    inner = content[b_start+1:b_end-1]
    # Determine which langs need fill
    existing = {}
    for lang in ['de','hu','ro','en']:
        lm = re.search(r'%s:\s*"((?:[^"\\]|\\.)*)"' % lang, inner)
        existing[lang] = len(lm.group(1)) if lm else 0
    need = [l for l in ['hu','ro','en'] if existing.get(l,0) < 50]
    if not need:
        continue
    new_block = build_new_block(inner, TEXTS[pid])
    content = content[:b_start] + new_block + content[b_end:]
    filled += 1
    total_langs_filled += len(need)

with open(PATH, 'w', encoding='utf-8') as f:
    f.write(content)

print(f'POIs updated: {filled}, language slots filled: {total_langs_filled}')
